    #[test]
    fn multi_page_receipt_renders() {
        // Generate many intro_paragraphs to force a page break
        let mut intros = Vec::new();
        for i in 0..40 {
            intros.push(format!(
                "Absatz Nummer {i}: lorem ipsum dolor sit amet, consectetur \
                 adipiscing elit. Sed do eiusmod tempor incididunt ut labore et \
                 dolore magna aliqua."
            ));
        }
        let doc = ClinicalPdfLayout {
            kind: "receipt".into(),
            practice_lines: practice(),
            header_right_lines: vec![],
            meta_lines: meta(),
            address_lines: vec!["Empfänger".into()],
            document_title: "RECEIPT".into(),
            document_subtitle: None,
            intro_paragraphs: intros,
            label_value_rows: vec![],
            two_column: None,
            tables: vec![],
            detail_records: vec![],
            totals: vec![LabelValue {
                label: "Total".into(),
                value: "100,00 €".into(),
                ..Default::default()
            }],
            closing_paragraphs: vec![],
            signature_lines: vec![],
            footer_meta_lines: vec![],
            clinician_professional_title: None,
            clinician_zanr: None,
            clinician_bsnr: None,
            logo_kv_json: None,
            locale: None,
            rtl: false,
            ..Default::default()
        };
        let pdf = render_clinical_layout(&doc).unwrap();
        let text = String::from_utf8_lossy(&pdf);
        // Sollte mehrere /Page-Objekte enthalten
        let page_objs = text.matches("/Type /Page ").count();
        assert!(
            page_objs >= 2,
            "expected multi-page PDF, got {} pages",
            page_objs
        );
    }

